/* Supplied tree specimens, shared atlases and instanced LODs. No procedural tree fallback. */
window.createAuthoredForest=async function(T,api){
 const lowTreeScale=.75; // Small/medium trees: 25% smaller, including crowns.
 const clock={value:0},rimColor={value:new T.Color('#9ebbd0')},rimPower={value:.5};
 const loader=new T.GLTFLoader(),textures=new T.TextureLoader(),load=name=>new Promise((ok,no)=>loader.load('assets/forest/'+name+'.glb',ok,undefined,no)),texture=name=>new Promise((ok,no)=>textures.load('assets/forest/'+name,ok,undefined,no));
 const assets=await Promise.all(['tall','low','small'].map(async name=>{const [g,normal,reflection,roughness]=await Promise.all([load(name),texture(name+'-normal.png'),texture(name+'-reflection.png'),texture(name+'-roughness.png')]);for(const t of [normal,reflection,roughness]){t.flipY=false;t.encoding=T.LinearEncoding;t.anisotropy=4;}return {name,g,normal,reflection,roughness}}));
 const windHeader='uniform float forestTime;varying float forestCrown;\n';
 const wind=`forestCrown=clamp(position.y,0.,1.);vec3 forestOrigin=(modelMatrix*vec4(0.,0.,0.,1.)).xyz;
 #ifdef USE_INSTANCING
 forestOrigin=(modelMatrix*instanceMatrix*vec4(0.,0.,0.,1.)).xyz;
 #endif
 float forestPhase=forestOrigin.x*.137+forestOrigin.z*.219;float forestBend=sin(forestTime*.53+forestPhase)*.009+sin(forestTime*.31+forestPhase*.7)*.004;
 float forestFlex=forestCrown*forestCrown;float forestLeaf=smoothstep(.28,.8,forestCrown)*.0025*sin(forestTime*1.65+forestPhase+position.x*17.+position.z*23.);
 transformed.x+=forestFlex*forestBend+forestLeaf;transformed.z+=forestFlex*cos(forestTime*.41+forestPhase)*.006+forestLeaf*.7;`;
 function motion(material,rim=false){const compile=material.onBeforeCompile,key=material.customProgramCacheKey.bind(material);material.onBeforeCompile=shader=>{compile.call(material,shader);shader.uniforms.forestTime=clock;shader.vertexShader=windHeader+shader.vertexShader;shader.vertexShader=shader.vertexShader.replace('#include <begin_vertex>','#include <begin_vertex>\n'+wind);if(rim){shader.uniforms.forestRimColor=rimColor;shader.uniforms.forestRimPower=rimPower;shader.fragmentShader='varying float forestCrown;uniform vec3 forestRimColor;uniform float forestRimPower;\n'+shader.fragmentShader;shader.fragmentShader=shader.fragmentShader.replace('#include <tonemapping_fragment>',`float forestTop=smoothstep(.62,.92,forestCrown);float forestEdge=pow(1.-abs(dot(normalize(normal),normalize(vViewPosition))),3.);float forestSky=.3+.7*max(0.,normal.y);gl_FragColor.rgb+=forestRimColor*forestRimPower*forestTop*forestEdge*forestSky;
 #include <tonemapping_fragment>`);}};material.customProgramCacheKey=()=>key()+'forest-wind-v1-'+rim;material.needsUpdate=true;return material;}
 const depth=motion(new T.MeshDepthMaterial({depthPacking:T.RGBADepthPacking,side:T.DoubleSide})),variants=[];
 for(const asset of assets){const source=asset.g.scene.getObjectByName('tree_0_full').material;const material=new T.MeshPhysicalMaterial({map:source.map,color:source.color.clone(),normalMap:asset.normal,normalScale:new T.Vector2(.38,.38),roughness:.94,roughnessMap:asset.roughness,metalness:0,clearcoat:.18,clearcoatMap:asset.reflection,clearcoatRoughness:.65,side:T.DoubleSide});api.mist(material);motion(material,true);for(let i=0;i<4;i++){const full=asset.g.scene.getObjectByName('tree_'+i+'_full'),mid=asset.g.scene.getObjectByName('tree_'+i+'_mid'),far=asset.g.scene.getObjectByName('tree_'+i+'_far');for(const m of [full,mid,far]){m.geometry.computeBoundingBox();m.geometry.computeBoundingSphere()}variants.push({name:asset.name,index:i,geometry:{full:full.geometry,mid:mid.geometry,far:far.geometry},material});}}
 const low=variants.filter(v=>v.name==='low'||v.name==='small'&&v.index<2),high=variants.filter(v=>v.name==='tall'),bushes=variants.filter(v=>v.name==='small'&&v.index>=2),batches=[];
 function specimen(variant,h=5){const mesh=new T.Mesh(variant.geometry.full,variant.material);mesh.scale.setScalar(h);mesh.castShadow=mesh.receiveShadow=true;mesh.customDepthMaterial=depth;return mesh;}
 function tree(seed=0,tall=false,h){const list=tall?high:low;return specimen(list[Math.abs(Math.floor(seed))%list.length],(h??(tall?10:5))*(tall?1:lowTreeScale));}
 function bush(seed=0,h=1.6){return specimen(bushes[Math.abs(Math.floor(seed))%bushes.length],h);}
 function plant(locations,world,records){const created=[];const buckets=new Map();for(const p of locations){const v=p.tall?high[p.variant%high.length]:low[p.variant%low.length],key=v.name+v.index+':'+Math.floor(p.x/24)+':'+Math.floor(p.z/24);if(!buckets.has(key))buckets.set(key,{v,list:[]});buckets.get(key).list.push(p)}for(const {v,list} of buckets.values()){const mesh=new T.InstancedMesh(v.geometry.mid,v.material,list.length),bounds=new T.Box3(),dummy=new T.Object3D();for(let i=0;i<list.length;i++){const p=list[i];dummy.position.set(p.x,p.y,p.z);dummy.rotation.set(p.tiltX||0,p.angle,p.tiltZ||0);dummy.scale.setScalar(p.height*(p.tall?1:lowTreeScale));dummy.updateMatrix();mesh.setMatrixAt(i,dummy.matrix);records.push({inst:mesh,index:i,key:p.key,matrix:dummy.matrix.clone()});const box=v.geometry.full.boundingBox.clone().applyMatrix4(dummy.matrix);bounds.union(box)}mesh.instanceMatrix.needsUpdate=true;mesh.frustumCulled=false;mesh.castShadow=mesh.receiveShadow=true;mesh.userData.outlineIgnore=true;mesh.customDepthMaterial=depth;world.add(mesh);const batch={mesh,geometry:v.geometry,bounds:bounds.expandByScalar(8),center:bounds.getCenter(new T.Vector3())};batches.push(batch);created.push(batch)}return created}
 function unplant(created){for(const batch of created){batch.mesh.parent?.remove(batch.mesh);batch.mesh.dispatchEvent({type:'dispose'});const i=batches.indexOf(batch);if(i>=0)batches.splice(i,1)}}
 const frustum=new T.Frustum(),matrix=new T.Matrix4();
 function update(dt,camera,pan,zoom,sky,key){clock.value+=dt;rimColor.value.copy(sky).lerp(key,.3);rimPower.value=.55;camera.updateMatrixWorld();matrix.multiplyMatrices(camera.projectionMatrix,camera.matrixWorldInverse);frustum.setFromProjectionMatrix(matrix);for(const b of batches){b.mesh.visible=frustum.intersectsBox(b.bounds);const d=Math.hypot(b.center.x-pan.x,b.center.z-pan.z),lod=zoom>1.2&&d<28?'full':d<58?'mid':'far';if(b.mesh.geometry!==b.geometry[lod])b.mesh.geometry=b.geometry[lod];}}
 return {tree,bush,plant,unplant,update,variants};
};
